'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var roundsdf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( roundsdf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof roundsdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns NaN if provided NaN', opts, function test( t ) {
	t.ok( isnan( roundsdf( NaN, 2, 10 ) ), 'x is NaN' );
	t.end();
});

tape( 'the function returns NaN if provided n < 1', opts, function test( t ) {
	t.ok( isnan( roundsdf( 3.14, 0, 10 ) ), 'n = 0' );
	t.ok( isnan( roundsdf( 3.14, -1, 10 ) ), 'n < 0' );
	t.end();
});

tape( 'the function returns NaN if provided base < 2', opts, function test( t ) {
	t.ok( isnan( roundsdf( 3.14, 2, 1 ) ), 'b = 1' );
	t.ok( isnan( roundsdf( 3.14, 2, 0 ) ), 'b = 0' );
	t.ok( isnan( roundsdf( 3.14, 2, -1 ) ), 'b < 0' );
	t.end();
});

tape( 'the function returns infinities unchanged', opts, function test( t ) {
	t.strictEqual( roundsdf( PINF, 3, 10 ), PINF, 'returns +infinity' );
	t.strictEqual( roundsdf( NINF, 3, 10 ), NINF, 'returns -infinity' );
	t.end();
});

tape( 'the function preserves signed zero', opts, function test( t ) {
	t.ok( isPositiveZero( roundsdf( 0.0, 2, 10 ) ), 'returns +0' );
	t.ok( isNegativeZero( roundsdf( -0.0, 2, 10 ) ), 'returns -0' );
	t.end();
});

tape( 'the function rounds to a specified number of significant figures (base 10)', opts, function test( t ) {
	t.strictEqual( roundsdf( 3.14159, 1, 10 ), 3.0, 'n=1' );
	t.strictEqual( roundsdf( 3.14159, 2, 10 ), 3.1, 'n=2' );
	t.strictEqual( roundsdf( 3.14159, 3, 10 ), 3.14, 'n=3' );
	t.strictEqual( roundsdf( 3.14159, 4, 10 ), 3.142, 'n=4' );
	t.end();
});

tape( 'the function rounds large values', opts, function test( t ) {
	t.strictEqual( roundsdf( 12368.0, 1, 10 ), 10000.0, 'n=1' );
	t.strictEqual( roundsdf( 12368.0, 2, 10 ), 12000.0, 'n=2' );
	t.strictEqual( roundsdf( 12368.0, 3, 10 ), 12400.0, 'n=3' );
	t.end();
});

tape( 'the function rounds negative values', opts, function test( t ) {
	t.strictEqual( roundsdf( -3.14159, 1, 10 ), -3.0, 'n=1' );
	t.strictEqual( roundsdf( -3.14159, 3, 10 ), -3.14, 'n=3' );
	t.strictEqual( roundsdf( -12368.0, 2, 10 ), -12000.0, 'n=2' );
	t.end();
});

tape( 'the function supports custom bases', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var v;

	v = roundsdf( 0.0313, 2, 2 );
	expected = 0.03125;

	if ( v === expected ) {
		t.strictEqual( v, expected, 'returns expected value' );
	} else {
		delta = abs( v - expected );
		tol = EPS * abs( expected );
		t.ok( delta <= tol, 'within tolerance' );
	}
	t.end();
});
